content.query:
let g = ClaudeChargeback(datetime({TimeRange:startISO}), datetime({TimeRange:endISO}))
| summarize reqs = todouble(count()), nocaller = todouble(countif(actor == 'unattributed')), nounit = todouble(countif(business_unit == 'unassigned')), noclient = todouble(countif(client_surface == 'unknown'));
g | project Metric = 'Requests', Value = reqs
| union (g | project Metric = 'No caller', Value = nocaller)
| union (g | project Metric = 'No business unit', Value = nounit)
| union (g | project Metric = 'No client', Value = noclient)
